  const bestCp = cpOfLine(pvs[0]);
  const brilliant = [];   // { san, loss }
  const cands = (await puzzleCandidatesAt(nextWorker(), preSans, pvs, fenRoot)) || [];
  for (const c of cands) if (c.kind === "brilliant") brilliant.push({ san: c.san, loss: c.loss });
