function seedContent() {
  if (CONTENT_SEEDED) return; CONTENT_SEEDED = true;
  const addMove = (posKey, san, kind) => {
    if (!CONTENT.treeAdds[posKey]) CONTENT.treeAdds[posKey] = [];
    if (!CONTENT.treeAdds[posKey].some((x) => x.san === san)) CONTENT.treeAdds[posKey].push({ san });
    const fk = posKey + "|" + san; if (kind && !(fk in CONTENT.forceKind)) CONTENT.forceKind[fk] = kind;
  };
  // 다미아노 디펜스: 1.e4 e5 2.Nf3 f6 3.Nxe5 fxe5 4.Qh5+  (2.Nc3는 3.Nxe5가 불가능하므로 정수인 Nf3로 수록)
  addMove("e4 e5 Nf3", "f6", "mistake");
  addMove("e4 e5 Nf3 f6", "Nxe5", "brilliant");
  addMove("e4 e5 Nf3 f6 Nxe5", "fxe5", "inaccuracy");
  addMove("e4 e5 Nf3 f6 Nxe5 fxe5", "Qh5+", "best");
  if (!("e4 e5 Nf3 f6 Nxe5 fxe5|Qh5+" in CONTENT.mainline)) CONTENT.mainline["e4 e5 Nf3 f6 Nxe5 fxe5|Qh5+"] = true;
  if (!("e4 e5 Nf3 f6 Nxe5|fxe5" in CONTENT.mainline)) CONTENT.mainline["e4 e5 Nf3 f6 Nxe5|fxe5"] = true;
  if (!("e4 e5 Nf3 f6|Nxe5" in CONTENT.mainline)) CONTENT.mainline["e4 e5 Nf3 f6|Nxe5"] = true;
  if (!("e4 e5 Nf3 f6 Nxe5 fxe5|Qh5+" in CONTENT.explains)) CONTENT.explains["e4 e5 Nf3 f6 Nxe5 fxe5|Qh5+"] = t("다미아노 디펜스 응징의 핵심. 4.Qh5+ 더블 어택으로 e5 폰 회수, 흑 킹 노출");
  // 폴란드 오프닝(1.b4)·폰지아니(1.e4 e5 2.Nf3 Nc6 3.c3) 이론 수 지정
  if (!("|b4" in CONTENT.forceKind)) CONTENT.forceKind["|b4"] = "book";
  addMove("e4 e5 Nf3 Nc6", "c3", "book");
  if (!("e4 e5 Nf3 Nc6|c3" in CONTENT.explains)) CONTENT.explains["e4 e5 Nf3 Nc6|c3"] = t("폰지아니 오프닝. d4를 준비하며 중앙을 노리는 고전 정석");
  // 카로칸: 백의 3번째 수를 분기점으로, 3.Nc3를 메인 라인으로
  CONTENT.mainline["e4 c6 d4 d5|Nc3"] = true;
  // 스칸디나비안 디펜스(1.e4 d5) — 스냅샷에서 누락되어 보강
  addMove("e4", "d5", "book");
  addMove("e4 d5", "exd5", "book");
  addMove("e4 d5 exd5", "Qxd5"); addMove("e4 d5 exd5", "Nf6");
  addMove("e4 d5 exd5 Qxd5", "Nc3", "book");
  addMove("e4 d5 exd5 Qxd5 Nc3", "Qa5"); addMove("e4 d5 exd5 Qxd5 Nc3", "Qd6"); addMove("e4 d5 exd5 Qxd5 Nc3", "Qd8");
  CONTENT.mainline["e4 d5|exd5"] = true; CONTENT.mainline["e4 d5 exd5|Qxd5"] = true; CONTENT.mainline["e4 d5 exd5 Qxd5|Nc3"] = true;
  if (!("e4 d5" in CONTENT.explains)) CONTENT.explains["e4 d5"] = t("스칸디나비안 디펜스. 흑이 d5로 중앙을 바로 교환해 빠르게 전개. 백은 2.exd5 뒤 퀸/나이트 회수 라인으로 분기");
  // 외부 마스터 게임 기반 이론 라인(THEORY_BOOK) 반영 — 각 라인을 한 수씩 훑으며
  // addMove로 이론 등록하고, 마지막 수의 도착 위치에만 이름을 붙인다(중간 위치는 이미 다른
  // 라인이 이름을 갖고 있을 수 있어 덮어쓰지 않음).
  for (const entry of THEORY_BOOK) {
    let posKey = "";
    entry.moves.forEach((san, i) => {
      addMove(posKey, san);
      if (i === entry.moves.length - 1 && entry.name) {
        const nk = posKey + "|" + san;
        if (!(nk in CONTENT.names)) CONTENT.names[nk] = entry.name;
      }
      posKey = posKey ? posKey + " " + san : san;
    });
  }
  seedLessons();
}
/* ============================================================ 레슨 (v0.4.0 메인 퀘스트 전면 개편) ============================================================ */
// (사용자 요청) "메인 퀘스트"(사지선다 챕터 퀴즈 나열)를 체스 개념·오프닝 하나하나를 다루는 독립된
// 학습 콘텐츠 "레슨"으로 전면 개편한다. 레슨은 서로 유기적으로 이어지도록 parents(선행 레슨 key
// 배열)로 연결해 갈래를 갖는 그래프(DAG) 구조를 이루고, 선행 레슨을 모두 완료(보상 수령)해야 다음
// 레슨이 열린다(도감 오프닝 모식도와 같은 "순차 해금" 원리) — 서로 다른 갈래가 하나의 레슨으로 다시
// 합류할 수도 있다(예: 두 오프닝 라인 모두 끝내야 열리는 "엔드게임 기초"). 레슨 하나 =
// { title, desc, parents:[...], reward, pages:[...] } (parents가 빈 배열이면 최상위 레슨). 옛
// 콘텐츠가 여전히 parent(단수) 하나만 갖고 있을 수도 있어, 실제로 읽을 때는 항상 이 필드를 직접
// 읽지 않고 lessonParents(lesson) 헬퍼(정규화해서 배열로 반환)를 통해서만 다룬다.
//
// (사용자 요청) 레슨은 여러 개의 "페이지"를 순서대로 진행하며, 이미 지나온 페이지는 뒤로 가서 다시
// 볼 수 있다. 페이지 하나 = { startSans?, flip?, beats:[...] } — beats는 정해진 스크립트로, 순서대로
// 재생되며 사용자와 상호작용한다. beat 종류(자세한 재생 로직은 LessonScreen 참고):
//   say        { speaker:"milku"|"kokoa", text, sans? }        코치 대사 한 줄(타이핑 애니메이션, 눌러서 다음)
//   principles { lines:[...] }                                 목록이 한 줄씩 떠올랐다 사라지는 자동 연출
//   mc         { prompt, opts:[...], answer, note, sans? }      객관식 — 정답을 고르면 통과
//   move       { prompt, answers:[...], note, sans? }           주관식 — 보드에 직접 수를 두면 통과
//   play       { moves:[...], stepMs? }                         현재 위치에서 이어서 수순을 빠르게 재생(자동)
//   pause      { ms }                                           잠시 대기(자동)
//   board      { squares:[...], dim?, glow?, siren?, arrows?, sans? }  보드 연출(칸 강조/음영/사이렌/화살표), 자동으로 다음 진행
//              arrows:[{ from, to, type:"attacker"|"defender" }, ...] — from/to는 칸 이름("e4") 문자열.
//              공격 기물→피격 기물 방향 화살표를 그린다. "attacker"는 빨간 화살표(위협하는 기물), "defender"는
//              초록 화살표(방어하는 기물) — Board의 threatAttacker/threatDefender 화살표 스타일을 그대로 재사용.
//   clear      { }                                               보드 연출 상태(화살표 포함)를 초기화
// 어떤 beat든 sans를 지정하면 그 자리에서 즉시(재생 없이) 그 위치로 전환된다.
// 모든 필드는 개발자가 CMS(LessonEditor)로 직접 입력·수정·삭제할 수 있고, CONTENT.lessons에 저장되어
// 전 유저에 반영된다.
// (기능) 파일(a~h) 전체 + 랭크(1~8) 전체를 합친 "십자" 모양 칸 목록 — d·e 파일과 4·5 랭크를 함께
// 강조하는 것처럼, 특정 열·행 전체를 하이라이트하는 레슨 연출에 쓴다.
function lessonCross(files, ranks) {
  const out = new Set();
  for (const f of files) for (let r = 1; r <= 8; r++) out.add(f + r);
  for (const r of ranks) for (const f of FILES) out.add(f + r);
  return [...out];
}
