  if (board[twoStepR] && board[twoStepR][fc]) return null; // 두 칸째가 애초에 막혀 있었으면 낭비가 아니다
  const ctrl = controlFacts(sansBeforeMove, san, color, fenRoot);
  if (ctrl.threats.length) return null; // 상대 기물을 쫓아내는 등 새 위협을 만들었다면 낭비가 아니다
