// 두 보드(내 보드/상대 보드) 위에 붙는 작은 이름표.
// (v0.5.1 UI, 사용자 요청) 미니게임 화면이 전체화면 어두운 배경으로 바뀌면서 밝은 잉크색(T.inkSoft)
// 대신 옅은 아이보리로 바꿨다 — flexShrink:0도 함께 줘 두 보드가 flex:1로 남은 공간을 나눠 가질 때
// 이 라벨 자신의 높이가 줄어들지 않게 한다.
function MinigameBoardLabel({ text }) {
  return <div style={{ textAlign: "center", fontSize: 11, fontWeight: 800, color: "rgba(90,58,34,.70)", marginBottom: 6, flexShrink: 0 }}>{text}</div>;
}
// ============================================================ 미니게임 전적·레이팅·랭킹(v0.5.4) ============================================================
// (v0.5.4 기능, 사용자 요청: "미니게임을 더 발전시키고 싶어" → 전적·레이팅·랭킹) 실시간 대전 결과는 서버
// 트리거(_minigame_on_game_end)가 minigame_stats에 쌓고, 혼자 플레이하기 기록은 minigame_submit_best로
// 올린다. 랜덤 매칭만 레이팅 대전이고 친구 도전·재대결은 전적만 남는다(pvp_games.rated). 레이팅 랭킹은
// 레이팅 대전 MINIGAME_PLACEMENT판 이상부터 오른다 — 서버 minigame_leaderboard의 조건과 같아야 한다.
export const MINIGAME_PLACEMENT = 3;
export function minigameBestFromServer(game, score, detail) {
  if (score == null) return null;
  if (game === "knight") {
    if (detail && detail.reached) return { reached: detail.reached, ms: detail.ms || 0 };
    const reached = Math.ceil(score / 1e6);
    return { reached, ms: reached * 1e6 - score };
  }
  return Number(score);
}
export function minigameBestLabel(game, v) {
  if (v == null) return null;
  if (game === "knight") return t("{0}회 도달 · {1}초", (v.reached), ((v.ms || 0) / 1000).toFixed(1));
  if (game === "coord") return t("{0}점", (v)); // (v0.5.7) 맞힌 개수 × 난이도 배율
  if (game === "rush") return "★" + v;
  if (game === "attack") return t("{0}회 메이트", (v));
  return String(v);
}
export async function fetchMinigameStats(uid) {
  if (!SB_ON || !uid) return {};
  const rows = await sbSelect("minigame_stats?uid=eq." + uid + "&select=game,rating,peak_rating,rated_games,games,wins,losses,draws,streak,best_streak,best_score,best_detail");
  const out = {};
  (rows || []).forEach((r) => { out[r.game] = r; });
  return out;
}
// (v0.6.2) 레이팅 칩 — 미니게임 허브 버튼 이름 옆에 붙던 금색 알약을 공용으로 뺐다. 일반 대국 타임 컨트롤 선택·/user 성취도 카드가 똑같이 쓴다.
// 배치(MINIGAME_PLACEMENT판)를 마친 레이팅만 보여준다 — 호출부가 placed를 판단해 넘긴다.
export const MG_RATING_GOLD = "#A97A2C";
export function MgRatingChip({ children, style }) {
  return <span style={{ fontSize: "clamp(9px, 2.2cqw, 14px)", fontWeight: 800, padding: "0.2em 0.6em", borderRadius: 999, background: "rgba(196,154,80,.18)", color: MG_RATING_GOLD, letterSpacing: 0, fontVariantNumeric: "tabular-nums", ...style }}>{children}</span>;
}
export function isPlacedStat(row) { return !!(row && row.rated_games >= MINIGAME_PLACEMENT); }
export function minigameRecordText(r) { return r ? t("{0}승 {1}패{2}", (r.wins), r.losses, r.draws ? t(" {0}무", r.draws) : "") : t("0승 0패"); }
export function MgOppBadge({ opp, size = 16, inline }) {
  if (!opp) return null;
  const base = { width: size, height: size, borderRadius: "50%", border: "1.5px solid #fff", boxShadow: "0 1px 3px rgba(0,0,0,.45)", overflow: "hidden", flexShrink: 0, display: "inline-flex", alignItems: "center", justifyContent: "center", pointerEvents: "none" };
  const pos = inline ? {} : { position: "absolute", top: 2, right: 2, zIndex: 5 };
  if (opp.bot) return <span aria-label={t("봇")} style={{ ...base, ...pos, background: "#3A2516", color: T.brassHi }}><Cpu size={Math.round(size * 0.62)} /></span>;
  if (opp.photo) return <img src={opp.photo} alt="" draggable={false} style={{ ...base, ...pos, objectFit: "cover", background: "#EDE1C6" }} />;
  return <span aria-label={opp.name || t("상대")} style={{ ...base, ...pos, background: "linear-gradient(180deg," + T.brass + ",#A8842F)", color: "#241509", fontSize: Math.round(size * 0.55), fontWeight: 900, lineHeight: 1 }}>{((opp.name || "?")[0] || "?").toUpperCase()}</span>;
}
/* ============================================================ 도감 탭 ============================================================ */
export function WinBar({ wdl, height = 8 }) {
  if (!wdl) return null;
  const tot = wdl.w + wdl.d + wdl.b; if (!tot) return null;
  const w = Math.round(100 * wdl.w / tot), d = Math.round(100 * wdl.d / tot), b = 100 - w - d;
  return (
    <div>
      <div style={{ display: "flex", height, borderRadius: 4, overflow: "hidden", border: "1px solid rgba(0,0,0,.25)" }}>
        <div style={{ width: w + "%", background: T.ivoryHi }} />
        <div style={{ width: d + "%", background: "#9C8A6A" }} />
        <div style={{ width: b + "%", background: "#241509" }} />
      </div>
      <div className="flex justify-between" style={{ fontSize: 9.5, color: T.inkSoft, marginTop: 2, fontFamily: SITE_FONT }}><span>{tx("백 {0}", w)}%</span><span>{tx("무 {0}", d)}%</span><span>{tx("흑 {0}", b)}%</span></div>
    </div>
  );
}
// (2차 개편) 클릭으로 한 단계씩 펼치던 방식을 버리고, 모든 갈래를 최소 3수까지는 무조건, 그 이후는
// 채택률이 20% 이상으로 유지되는 한 계속 자동으로 탐색해 미리 다 펼쳐진 거대한 트리를 만든다.
